// fonts-arial.js - polices Arimo (metrique-compatible Arial, licence Apache 2.0, Google Fonts)
// embarquees pour que le PDF genere utilise une police visuellement fidele a la version Word (Arial).
(function () {
  if (typeof pdfMake === "undefined" || !pdfMake.addVirtualFileSystem) return;
  var arimoVfs = {
    "Arimo-Regular.ttf": "",
    "Arimo-Bold.ttf": "",
    "Arimo-Italic.ttf": "",
    "Arimo-BoldItalic.ttf": ""
  };
  // vfs_fonts.js (charge juste avant) declare "var vfs" au niveau global -> window.vfs : on fusionne
  // au lieu de remplacer, addVirtualFileSystem() ecrase entierement le vfs interne a chaque appel.
  var merged = {};
  if (typeof vfs === "object" && vfs) { for (var k in vfs) merged[k] = vfs[k]; }
  for (var k2 in arimoVfs) merged[k2] = arimoVfs[k2];
  pdfMake.addVirtualFileSystem(merged);
  pdfMake.fonts = pdfMake.fonts || {};
  pdfMake.fonts.Arial = { normal: "Arimo-Regular.ttf", bold: "Arimo-Bold.ttf", italics: "Arimo-Italic.ttf", bolditalics: "Arimo-BoldItalic.ttf" };
})();
